{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Gatherings — Events | {{BUSINESS_NAME}}</title>
  <meta name="description" content="Group sound & restorative sessions in {{CITY}}, {{STATE}} — drop-in events, themed nights, and a calm-first approach.">
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--accent:#8fe3d1;--muted:#99a0a7;--glass:rgba(255,255,255,0.04);font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial}
    html,body{height:100%}
    body{margin:0;background:linear-gradient(180deg,#07101a 0%,#081018 40%);color:#e6eef0}
    header{position:relative;padding:36px 28px 18px;display:flex;align-items:center;justify-content:space-between}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-weight:600}
    nav a.active{color:var(--accent)}
    .brand{font-weight:700;letter-spacing:0.6px}
    .hero{padding:36px 28px 48px;display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:start}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border-radius:12px;padding:22px;box-shadow:0 6px 20px rgba(2,6,23,0.6)}
    .hero h1{margin:0 0 8px;font-size:28px}
    .meta{color:var(--muted);font-size:14px;margin-bottom:12px}
    .next-event{display:flex;flex-direction:column;gap:14px}
    .next-card{background:var(--card);padding:18px;border-radius:10px}
    .date{font-weight:700;color:var(--accent);font-size:18px}
    .when{font-size:13px;color:var(--muted)}
    .join{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#082022;border-radius:10px;text-decoration:none;font-weight:700}
    .list{margin-top:18px;display:grid;gap:10px}
    .event-item{display:flex;justify-content:space-between;padding:12px;border-radius:8px;background:linear-gradient(90deg,rgba(255,255,255,0.012),transparent);align-items:center}
    .small{font-size:13px;color:var(--muted)}
    .mood-card{padding:18px;border-radius:12px;background:linear-gradient(180deg,#08121a,transparent);}
    .mood-toggle{display:flex;gap:8px;flex-wrap:wrap}
    .mood-toggle button{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:8px 10px;border-radius:8px;color:var(--muted);cursor:pointer}
    .mood-toggle button.active{border-color:var(--accent);color:var(--accent);box-shadow:0 6px 16px rgba(31,196,172,0.08)}
    .recommended{margin-top:14px;padding:12px;border-radius:10px;background:rgba(143,227,209,0.04)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;background:#0b84a5;border-radius:10px;color:white;text-decoration:none;font-weight:700}
    footer{padding:28px;color:var(--muted);font-size:13px;text-align:center}
    .disclaimer{margin-top:16px;font-size:12px;color:#f2c7c7;background:rgba(255,115,115,0.03);padding:10px;border-radius:8px}
    /* decorative SVG blob */
    .pattern{position:absolute;right:10px;top:6px;opacity:0.08;width:320px;height:200px}
    @media (max-width:880px){.hero{grid-template-columns:1fr;}.pattern{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html" class="active">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">Our Story</a>
      <a href="faq.html">Q&amp;A</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="panel">
        <h1>Open sessions & themed evenings</h1>
        <div class="meta">Drop in, tune down, and leave clearer — sessions designed for modern schedules.</div>

        <div class="panel mood-card">
          <h3 style="margin:0 0 8px">Mood-to-Method</h3>
          <div class="small">Select how you feel and we’ll suggest the best group format.</div>
          <div class="mood-toggle" role="tablist" aria-label="Mood selector">
            <button data-mood="anxious">Anxious</button>
            <button data-mood="tired">Tired</button>
            <button data-mood="scattered">Scattered</button>
            <button data-mood="curious">Curious</button>
            <button data-mood="celebratory">Celebratory</button>
          </div>
          <div class="recommended" id="recommended">
            <strong id="methodTitle">Choose a mood</strong>
            <div id="methodDesc" class="small">We’ll adjust the session focus and the suggested length.</div>
            <a id="moodCta" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="disclaimer">Contraindications: If you are pregnant, have a history of seizures, severe PTSD, uncontrolled psychiatric conditions, or are currently under a course of treatment where sound exposure is contraindicated, please consult your healthcare provider before attending. Reach out at {{EMAIL}} for guidance.</div>

      </div>

      <aside class="panel next-event">
        <div style="display:flex;justify-content:space-between;align-items:start">
          <div>
            <div class="small">Next gathering</div>
            <div class="date">Saturday, Mar 6 • 6:30–8:00pm</div>
            <div class="when">Community Hall — {{CITY}}, {{STATE}}</div>
          </div>
          <div>
            <a class="join" href="book.html">Reserve a seat</a>
          </div>
        </div>

        <div style="margin-top:12px" class="small">Theme: "Slow Return" — an accessible sequence blending sustained tones and guided breath. Capacity limited.</div>

        <div class="list" aria-live="polite">
          <div class="event-item"><div><strong>Wed, Feb 25</strong><div class="small">Lush Evening — 7:00pm</div></div><div class="small">7 seats</div></div>
          <div class="event-item"><div><strong>Sat, Mar 6</strong><div class="small">Slow Return — 6:30pm</div></div><div class="small">12 seats</div></div>
          <div class="event-item"><div><strong>Tue, Mar 16</strong><div class="small">Deep Pause — 6:00pm</div></div><div class="small">9 seats</div></div>
          <div class="event-item"><div><strong>Sat, Apr 3</strong><div class="small">Sound & Sketch — 4:00pm</div></div><div class="small">15 seats</div></div>
        </div>

      </aside>

      <svg class="pattern" viewBox="0 0 600 400" xmlns="http://www.w3.org/2000/svg" aria-hidden>
        <defs>
          <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7fe8d1" stop-opacity="0.25"/><stop offset="1" stop-color="#7fc6ff" stop-opacity="0.12"/></linearGradient>
        </defs>
        <g fill="url(#g1)">
          <path d="M38.6,-50.7C51.9,-38.7,61.3,-26,66.9,-11.8C72.6,2.4,74.6,17.8,69.7,30.8C64.8,43.8,53,54.4,39.4,60C25.8,65.6,10.4,66.2,-2.9,69.1C-16.1,72,-32.2,77.1,-45.4,72.6C-58.7,68.2,-69,54.1,-72.1,38.4C-75.3,22.8,-71.5,5.6,-63.4,-8.8C-55.3,-23.3,-42.9,-35.2,-29.9,-47.7C-16.9,-60.2,-8.5,-73.3,5.1,-81.2C18.8,-89,37.5,-91,38.6,-50.7Z" transform="translate(300 200) scale(1.2)"/>
        </g>
      </svg>

    </section>
  </main>

  <footer>
    <div>Questions? Call {{PHONE}} • <a href="mailto:{{EMAIL}}" style="color:var(--muted)">{{EMAIL}}</a></div>
    <div style="margin-top:8px">Events calendar updated weekly. For private bookings, see Private tab.</div>
  </footer>

  <script>
    // Mood-to-Method: local interactivity
    (function(){
      const buttons = document.querySelectorAll('.mood-toggle button');
      const title = document.getElementById('methodTitle');
      const desc = document.getElementById('methodDesc');
      const cta = document.getElementById('moodCta');

      const map = {
        anxious: {
          title:'Anchoring Session',
          desc:'Short, sustained tones with breath anchors—designed to steady the nervous system (30–40 mins).',
          ctaText:'Book an Anchoring Seat',
          href:'book.html?type=anchoring'
        },
        tired: {
          title:'Gentle Resurface',
          desc:'Soft harmonic layering to ease into rest without drowsiness (40–50 mins).',
          ctaText:'Reserve Gentle Resurface',
          href:'book.html?type=gentle'
        },
        scattered: {
          title:'Focused Sound Frame',
          desc:'Rhythmic pulses and brief guidance to rebuild attention (35–45 mins).',
          ctaText:'Reserve a Focus Seat',
          href:'book.html?type=focus'
        },
        curious: {
          title:'Experiment Night',
          desc:'Playful ritual with varied instruments — for exploration and creative rest (50–70 mins).',
          ctaText:'Join Experiment Night',
          href:'book.html?type=experiment'
        },
        celebratory: {
          title:'Collective Lift',
          desc:'Uplifting, communal sound with singable tones — a social slow-down (45–60 mins).',
          ctaText:'Book Collective Lift',
          href:'book.html?type=collective'
        }
      };

      function setMood(m){
        const data = map[m];
        title.textContent = data.title;
        desc.textContent = data.desc;
        cta.textContent = data.ctaText;
        cta.href = data.href;
      }

      buttons.forEach(b=>b.addEventListener('click',()=>{
        buttons.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        setMood(b.dataset.mood);
      }));

      // Seed default to curious
      const seed = 'curious';
      const btn = document.querySelector('.mood-toggle button[data-mood="'+seed+'"]');
      if(btn) { btn.click(); }
    })();
  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Private Work & Tailored Sessions | {{BUSINESS_NAME}}</title>
  <meta name="description" content="One-on-one and small-group private sessions: bespoke sound, outcome-focused sessions for life transitions and targeted support.">
  <style>
    :root{--bg:#fcfcff;--ink:#0b1720;--soft:#eef6f7;--accent:#2da79a;--muted:#5a6b6e}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;background:linear-gradient(180deg,#fbfefe 0%,#f3fafb 100%);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 28px}
    nav a{margin:0 12px;color:var(--muted);text-decoration:none;font-weight:600}
    nav a.active{color:var(--accent)}
    .hero{padding:28px;display:flex;gap:20px;align-items:flex-start}
    .card{background:white;border-radius:12px;box-shadow:0 6px 24px rgba(11,23,32,0.06);padding:20px;max-width:760px}
    .right{width:320px}
    h1{margin:4px 0 6px}
    .note{color:var(--muted);font-size:14px}
    .pillars{display:flex;gap:12px;margin-top:14px}
    .pillar{flex:1;background:linear-gradient(180deg,rgba(45,167,154,0.06),transparent);padding:12px;border-radius:8px}
    .mood-select{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
    .mood-select button{border:1px solid #e6f4f3;background:white;padding:8px 10px;border-radius:8px;cursor:pointer}
    .mood-view{margin-top:14px;padding:14px;border-radius:10px;background:linear-gradient(180deg,#f6fdfc,#ffffff)}
    .mood-title{font-weight:700}
    .session-cta{display:inline-block;margin-top:10px;padding:10px 14px;background:var(--accent);color:white;border-radius:10px;text-decoration:none}
    .case-notes{margin-top:18px;padding:12px;background:#f9fffe;border-radius:10px;font-size:13px}
    .contra{font-size:13px;color:#9b2b2b;background:#fff0f0;padding:10px;border-radius:8px;margin-top:12px}
    footer{padding:18px;text-align:center;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html" class="active">Private</a>
      <a href="pricing.html">Invest</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="card">
        <h1>Private work that meets the moment</h1>
        <div class="note">Tailored sessions for transitions, performance preparation, grief work, and sleep recalibration. Built to be effective and time-smart.</div>

        <div class="pillars">
          <div class="pillar">
            <strong>Assessment First</strong>
            <div class="note">We start with a short intake to shape tone, length, and markers of success.</div>
          </div>
          <div class="pillar">
            <strong>Practical Tools</strong>
            <div class="note">Sessions include takeaways you can use between meetings—anchor phrases, brief practices.</div>
          </div>
          <div class="pillar">
            <strong>Flexible Frames</strong>
            <div class="note">Single sessions, short series, or monthly touch-ins.</div>
          </div>
        </div>

        <div style="margin-top:16px">
          <h3 style="margin:0 0 6px">Mood-to-Method — pick how you are right now</h3>
          <div class="note">We’ll recommend an approach and update the booking CTA wording to match the outcome.</div>

          <div class="mood-select" id="moodButtons">
            <button data-id="reset">Not sure</button>
            <button data-id="recovery">Recovering</button>
            <button data-id="focus">Need Focus</button>
            <button data-id="sleep">Sleep Reset</button>
            <button data-id="transition">In Transition</button>
          </div>

          <div class="mood-view" id="moodView">
            <div class="mood-title" id="moodName">Choose a mood</div>
            <div id="moodSummary" class="note">We’ll suggest session length, instrument focus, and a personalised next step.</div>
            <div id="moodPackage" style="margin-top:8px"></div>
            <a id="moodBook" class="session-cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
          </div>

        </div>

        <div class="case-notes">
          <strong>Case notes (example):</strong>
          <div style="margin-top:8px">Client: early-career, presenting with chronic low-grade anxiety. Plan: three 45-min private sessions focusing on breath anchors and low-frequency sonic scaffolding. Outcome: improved sleep latency at 2-week check-in.</div>
        </div>

        <div class="contra">Contraindications reminder: If you have photosensitive epilepsy, certain cardiac devices, or active psychosis, please contact your clinician before booking. We’re happy to advise—email: {{EMAIL}}.</div>

      </div>

      <aside class="right card">
        <h3 style="margin-top:0">How private sessions are framed</h3>
        <div class="note">We structure private work as short cycles. Typical options:</div>
        <ul style="padding-left:18px">
          <li>Single: 60 minutes — intake + focused session</li>
          <li>Short series: three 45-minute sessions — deepening and practice</li>
          <li>Touch-ins: monthly check + recalibration</li>
        </ul>

        <div style="margin-top:10px"><a class="session-cta" href="contact.html">Request a custom plan</a></div>

      </aside>
    </section>
  </main>

  <footer>
    <div>Phone: {{PHONE}} • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:8px">Sessions by appointment only. Sliding scale and limited concessions available.</div>
  </footer>

  <script>
    // Mood-to-Method interactivity (private sessions)
    (function(){
      const btns = document.querySelectorAll('#moodButtons button');
      const name = document.getElementById('moodName');
      const summary = document.getElementById('moodSummary');
      const pack = document.getElementById('moodPackage');
      const book = document.getElementById('moodBook');

      const options = {
        reset:{title:'Not sure yet',summary:'A single 60-min intake session is a good first step. We clarify goals and immediate practice.',package:'60 min intake — single session',cta:'Book an Intake',href:'book.html?private=intake'},
        recovery:{title:'Recovering',summary:'Lower-frequency instruments, breath-paced guidance, follow-up check-ins. Short series recommended.',package:'3×45-min supportive series',cta:'Start a Recovery Series',href:'book.html?private=recovery'},
        focus:{title:'Need Focus',summary:'Tonal framing and attention scaffolds to increase focus and presence. One-off with optional follow-up.',package:'Single 45-min focus session',cta:'Reserve Focus Session',href:'book.html?private=focus'},
        sleep:{title:'Sleep Reset',summary:'Evening-oriented sequencing, gentle decelerations, and audio tools for home use.',package:'Single 60-min + nighttime recording',cta:'Book Sleep Reset',href:'book.html?private=sleep'},
        transition:{title:'In Transition',summary:'Short series that orients through change—30–60 minute frames depending on need.',package:'Short series (3 x 45-min)',cta:'Plan a Transition Series',href:'book.html?private=transition'}
      };

      btns.forEach(b=>b.addEventListener('click',()=>{
        btns.forEach(x=>x.style.outline='');
        b.style.outline='2px solid rgba(45,167,154,0.15)';
        const opt = options[b.dataset.id];
        name.textContent = opt.title;
        summary.textContent = opt.summary;
        pack.textContent = opt.package;
        book.textContent = opt.cta;
        book.href = opt.href;
      }));

      // Default selection
      document.querySelector('#moodButtons button[data-id="reset"]').click();
    })();
  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Pricing & Packages | {{BUSINESS_NAME}}</title>
  <meta name="description" content="Transparent pricing for drop-in events, private sessions, and packaged support. Toggle between monthly subscription and upfront package pricing.">
  <style>
    :root{--bg:#0b1320;--card:#09111a;--accent:#ffd166;--muted:#9fb4bb}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;background:var(--bg);color:#e9f4f4}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    nav a.active{color:var(--accent)}
    .wrap{padding:28px;display:flex;gap:18px}
    .left{flex:1}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px}
    .toggle{display:inline-flex;border-radius:999px;background:rgba(255,255,255,0.02);padding:6px;border:1px solid rgba(255,255,255,0.03)}
    .toggle button{background:transparent;border:0;color:var(--muted);padding:8px 12px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:var(--accent);color:#061219;font-weight:700}
    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}
    .plan{padding:16px;border-radius:10px;background:rgba(255,255,255,0.02);text-align:center}
    .price{font-size:28px;font-weight:800;margin-top:8px}
    .note{color:var(--muted);font-size:13px;margin-top:8px}
    .action{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#061219;border-radius:10px;text-decoration:none;font-weight:700}
    .comp{margin-top:12px;color:var(--muted);font-size:13px}
    footer{padding:18px;color:var(--muted);text-align:center}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html" class="active">Invest</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="left">
      <div class="card">
        <h2 style="margin:0">Pricing comparator</h2>
        <div class="note">Toggle to compare Monthly subscription vs Upfront package investments. Numbers animate to help you feel the difference.</div>

        <div style="margin-top:12px">
          <div class="toggle" role="tablist" aria-label="Pricing toggle">
            <button id="monthlyBtn" class="active">Monthly</button>
            <button id="packageBtn">Package</button>
          </div>
        </div>

        <div class="plans" id="plans">
          <div class="plan">
            <div class="small">Solo Session</div>
            <div class="price" data-month="45" data-package="120">$<span>45</span></div>
            <div class="note">Per drop-in / private intensity</div>
            <a class="action" id="cta1" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="plan">
            <div class="small">Short Series</div>
            <div class="price" data-month="120" data-package="320">$<span>120</span></div>
            <div class="note">Monthly or 3-session pack</div>
            <a class="action" id="cta2" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="plan">
            <div class="small">Membership Rhythm</div>
            <div class="price" data-month="65" data-package="180">$<span>65</span></div>
            <div class="note">Access to monthly group sessions + priority booking</div>
            <a class="action" id="cta3" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="comp">Tip: Packages are priced to encourage a short commitment; monthly is for regular touch-ins. Animations help compare totals at a glance.</div>
      </div>

      <div style="margin-top:12px" class="card">
        <h3 style="margin:0">Payment options</h3>
        <div class="note" style="margin-top:8px">Cards accepted. Sliding scale for qualifying participants; get in touch at {{EMAIL}}. Receipt and simple invoices available.</div>
      </div>
    </div>

    <aside style="width:320px">
      <div class="card">
        <h3 style="margin-top:0">Quick math</h3>
        <div class="note">See total over a quarter or a year by toggling and watching the numbers change.</div>
        <div style="margin-top:12px">
          <strong>3 months total:</strong>
          <div id="quarterTotal" style="font-size:22px;margin-top:6px">$<span>0</span></div>
          <div class="note" style="margin-top:8px">Numbers animate to show the visible difference between paying monthly vs upfront.</div>
        </div>
      </div>
    </aside>

  </main>

  <footer>
    <div>For custom packages and concessions, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}</div>
  </footer>

  <script>
    // Pricing comparator with animated numbers
    (function(){
      const monthlyBtn = document.getElementById('monthlyBtn');
      const packageBtn = document.getElementById('packageBtn');
      const prices = document.querySelectorAll('.price');
      const quarter = document.getElementById('quarterTotal').querySelector('span');

      let mode = 'monthly';

      function animateValue(el, start, end, duration){
        const span = el.querySelector('span');
        const startTime = performance.now();
        requestAnimationFrame(function tick(now){
          const t = Math.min((now - startTime)/duration,1);
          const curr = Math.round(start + (end-start)*t);
          span.textContent = curr;
          if(t<1) requestAnimationFrame(tick);
        });
      }

      function update(modeType){
        let totalQuarter = 0;
        prices.forEach(p=>{
          const m = parseInt(p.dataset.month,10);
          const pkg = parseInt(p.dataset.package,10);
          const target = modeType === 'monthly' ? m : pkg;
          const current = parseInt(p.querySelector('span').textContent,10) || 0;
          animateValue(p, current, target, 500);
          totalQuarter += target * (modeType === 'monthly' ? 3 : 1);
        });
        // animate quarter total
        const currTotal = parseInt(quarter.textContent,10) || 0;
        const startTime = performance.now();
        requestAnimationFrame(function tick(now){
          const t = Math.min((now - startTime)/600,1);
          const curr = Math.round(currTotal + (totalQuarter - currTotal)*t);
          quarter.textContent = curr;
          if(t<1) requestAnimationFrame(tick);
        });
      }

      monthlyBtn.addEventListener('click',function(){
        mode = 'monthly';
        monthlyBtn.classList.add('active'); packageBtn.classList.remove('active');
        update('monthly');
      });

      packageBtn.addEventListener('click',function(){
        mode = 'package';
        packageBtn.classList.add('active'); monthlyBtn.classList.remove('active');
        update('package');
      });

      // Initial render
      update(mode);

      // Small accessibility: toggle with keyboard
      monthlyBtn.addEventListener('keydown',e=>{ if(e.key==='Enter') monthlyBtn.click(); });
      packageBtn.addEventListener('keydown',e=>{ if(e.key==='Enter') packageBtn.click(); });
    })();
